import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  // Everything is static; derivatives are pre-generated by `npm run ingest`,
  // so Next's on-demand image optimizer is never used.
  poweredByHeader: false,
  turbopack: {
    rules: {
      "*.css": {
        loaders: ["@tailwindcss/turbopack"],
        as: "*.css",
      },
    },
  },
  async redirects() {
    // The New Jersey chapter used to be called Montclair.
    return [{ source: "/chapters/montclair", destination: "/chapters/new-jersey", permanent: true }];
  },
  async headers() {
    return [
      {
        source: "/globe/:file*",
        headers: [{ key: "Cache-Control", value: "public, max-age=31536000, immutable" }],
      },
      {
        source: "/:path*",
        headers: [
          { key: "X-Content-Type-Options", value: "nosniff" },
          { key: "Referrer-Policy", value: "strict-origin-when-cross-origin" },
          { key: "Permissions-Policy", value: "camera=(), microphone=(), geolocation=()" },
        ],
      },
    ];
  },
};

export default nextConfig;
